# ruff: noqa
import random
import copy
import collections
from typing import Any, Protocol, runtime_checkable
from enum import Enum

TO_PLAY = 'to_play'
TURN = 'turn'
PLY = 'ply'
UNKNOWN = 'unknown'
LABEL = 'label'
SLOT = 'slot'
COUNT = 'count'
OPTIONS = 'options'
COMPONENTS = 'components'
UNAVAILABLE = 'unavailable'

NAME = "sushigo"
PLAYERS = ('automa', 'human')

class Viewer(Enum):
    PUBLIC = 'public'
    AUTOMA = 'automa'
    HUMAN = 'human'

DECK_COMPOSITION = {
    "tempura": 14,
    "sashimi": 14,
    "dumpling": 14,
    "2_maki_rolls": 12,
    "3_maki_rolls": 8,
    "1_maki_roll": 6,
    "salmon_nigiri": 10,
    "squid_nigiri": 5,
    "egg_nigiri": 5,
    "pudding": 10,
    "wasabi": 6,
    "chopsticks": 4
}

SUPPORTED_OPS = {
    "gain",
    "multiply_next",
    "score_at_end",
    "score_flat",
    "score_majority",
    "score_per_resource",
    "score_per_set",
    "score_tiered",
    "set_flag"
}

TERMS = {
    "flag": {"chopsticks"},
    "count_field": {"maki", "pudding"},
    "category": {"nigiri"}
}

State = dict[str, Any]
Action = dict[str, Any]

def initial_state(seed: int | None = None) -> State:
    deck = []
    for card_type, count in DECK_COMPOSITION.items():
        deck.extend([card_type] * count)
    if seed is not None:
        random.Random(seed).shuffle(deck)
        
    state = {
        TO_PLAY: "automa",
        TURN: 0,
        PLY: 0,
        "round": 1,
        "deck": deck,
        "hands": {
            "automa": [],
            "human": []
        },
        "tableaus": {
            "automa": [],
            "human": []
        },
        "puddings": {
            "automa": [],
            "human": []
        },
        "discard": [],
        "scores": {
            "automa": 0,
            "human": 0
        },
        "pending_choices": {
            "automa": None,
            "human": None
        },
        "catalog": {
            "effects": {},
            "described": []
        },
        UNKNOWN: None,
        "_resume": None
    }
    return check_and_request_unknown(state)

#: `_resume` names which continuation `resolve_unknown` must run once a `card_effect`
#: question raised mid-round is answered. A card's effect can be asked about at three
#: different points - dealing time, right after an ordinary turn, and right after the
#: round's last card - and each leaves the state in a different shape to resume from.
#: Recomputing "what comes next" from state alone (e.g. from hand sizes) is what the
#: original version of this module did, and it broke: by the time a round's last card
#: had been added, hands were already emptied for scoring, so nothing distinguished
#: "about to play the last card" from "already played it, waiting on a question".
RESUME_AFTER_TURN = "after_turn_cards"
RESUME_AFTER_FINAL_CARD = "after_final_card"


def _find_unknown_active_card(state: State) -> dict[str, Any] | None:
    """The first card type on the table whose effect nothing has recorded, or None.

    Must be called at the moment a card enters a tableau or the pudding pile - not only
    when a hand is dealt or a round starts - because `score_round` reads this same
    catalog and then discards or reassigns every tableau card. A card checked for only
    at deal time can be played, scored as worth nothing because its effect was never on
    file, and swept away before this function is next given a chance to see it.
    """
    all_active_cards = set()
    for p in PLAYERS:
        all_active_cards.update([c["card_type"] for c in state["tableaus"][p]])
        all_active_cards.update(state["puddings"][p])

    effects = state["catalog"]["effects"]
    described = state["catalog"]["described"]

    for card_type in sorted(all_active_cards):
        if card_type not in effects and card_type not in described:
            return {
                "kind": "card_effect",
                "card_type": card_type,
                "prompt": f"Please describe the effect of card type '{card_type}'."
            }
    return None


def check_and_request_unknown(state: State) -> State:
    if state["round"] <= 3:
        if not state["hands"]["automa"]:
            state[UNKNOWN] = {
                "kind": "components",
                "slot": "hand.automa",
                "count": 10,
                "prompt": "Please enter the 10 cards dealt to the Automa player, separated by spaces.",
                "options": list(DECK_COMPOSITION.keys())
            }
            return state
        if not state["hands"]["human"]:
            state[UNKNOWN] = {
                "kind": "components",
                "slot": "hand.human",
                "count": 10,
                "prompt": "Please enter the 10 cards dealt to the Human player, separated by spaces.",
                "options": list(DECK_COMPOSITION.keys())
            }
            return state

    state[UNKNOWN] = _find_unknown_active_card(state)
    return state


def _after_turn_cards_played(state: State) -> State:
    """Resume point: this turn's chosen cards were just added to both tableaus."""
    unknown = _find_unknown_active_card(state)
    if unknown is not None:
        state[UNKNOWN] = unknown
        state["_resume"] = RESUME_AFTER_TURN
        return state

    hand_size = len(state["hands"]["automa"])
    if hand_size > 1:
        state["hands"]["automa"], state["hands"]["human"] = state["hands"]["human"], state["hands"]["automa"]
        state[TO_PLAY] = "automa"
        return state
    if hand_size == 1:
        for player in PLAYERS:
            last_card = state["hands"][player][0]
            state["hands"][player] = []
            unpaired_wasabi = next((c for c in state["tableaus"][player] if c["card_type"] == "wasabi" and not c.get("paired")), None)
            if unpaired_wasabi and "nigiri" in last_card:
                unpaired_wasabi["paired"] = True
                state["tableaus"][player].append({"card_type": last_card, "multiplier": 3})
            elif last_card == "wasabi":
                state["tableaus"][player].append({"card_type": last_card, "multiplier": 1, "paired": False})
            else:
                state["tableaus"][player].append({"card_type": last_card, "multiplier": 1})
        return _after_final_card_played(state)
    return state


def _after_final_card_played(state: State) -> State:
    """Resume point: the round's very last card was just added to both tableaus."""
    unknown = _find_unknown_active_card(state)
    if unknown is not None:
        state[UNKNOWN] = unknown
        state["_resume"] = RESUME_AFTER_FINAL_CARD
        return state

    state = score_round(state)
    state["round"] += 1

    if state["round"] <= 3:
        state["hands"]["automa"] = []
        state["hands"]["human"] = []
        state[TO_PLAY] = "automa"
        return check_and_request_unknown(state)
    return score_game_end(state)

def resolve_unknown(state: State, answer: dict[str, Any]) -> State:
    new_state = copy.deepcopy(state)
    q = new_state.get(UNKNOWN)
    if not q:
        return new_state
    resume = new_state.get("_resume")

    if q.get("kind") == "components":
        slot = q["slot"]
        player = "automa" if "automa" in slot else "human"
        
        if answer.get(UNAVAILABLE):
            dealt = []
            for _ in range(10):
                if new_state["deck"]:
                    dealt.append(new_state["deck"].pop(0))
            new_state["hands"][player] = dealt
        else:
            dealt_raw = answer.get("components", [])
            dealt = []
            for item in dealt_raw:
                cleaned = item.lower().strip().replace(" ", "_")
                matched = None
                for k in DECK_COMPOSITION.keys():
                    if cleaned == k:
                        matched = k
                        break
                if matched:
                    dealt.append(matched)
                else:
                    dealt.append(cleaned)
                    
            new_state["hands"][player] = dealt
            for card in dealt:
                if card in new_state["deck"]:
                    new_state["deck"].remove(card)
                elif new_state["deck"]:
                    new_state["deck"].pop(0)
                    
        new_state[UNKNOWN] = None
        new_state["_resume"] = None
        return check_and_request_unknown(new_state)

    elif q.get("kind") == "card_effect":
        card_type = q["card_type"]
        if answer.get(UNAVAILABLE):
            new_state["catalog"]["described"].append(card_type)
        else:
            effects = answer.get("effects", [])
            new_state["catalog"]["effects"][card_type] = effects
            new_state["catalog"]["described"].append(card_type)

        new_state[UNKNOWN] = None
        new_state["_resume"] = None
        if resume == RESUME_AFTER_TURN:
            return _after_turn_cards_played(new_state)
        if resume == RESUME_AFTER_FINAL_CARD:
            return _after_final_card_played(new_state)
        return check_and_request_unknown(new_state)

    return new_state

def score_round(state: State) -> State:
    new_state = copy.deepcopy(state)
    maki_counts = {"automa": 0, "human": 0}
    for p in PLAYERS:
        for card in new_state["tableaus"][p]:
            card_type = card["card_type"]
            effects = new_state["catalog"]["effects"].get(card_type, [])
            for op in effects:
                if op.get("op") == "gain" and op.get("resource") == "maki":
                    maki_counts[p] += op.get("amount", 0)
                    
    first_maki = 6
    second_maki = 3
    for effects in new_state["catalog"]["effects"].values():
        for op in effects:
            if op.get("op") == "score_majority" and op.get("count_field") == "maki":
                first_maki = op.get("first", 6)
                second_maki = op.get("second", 3)
                
    m_a = maki_counts["automa"]
    m_h = maki_counts["human"]
    if m_a > 0 or m_h > 0:
        if m_a > m_h:
            new_state["scores"]["automa"] += first_maki
            if m_h > 0:
                new_state["scores"]["human"] += second_maki
        elif m_h > m_a:
            new_state["scores"]["human"] += first_maki
            if m_a > 0:
                new_state["scores"]["automa"] += second_maki
        else:
            split = first_maki // 2
            new_state["scores"]["automa"] += split
            new_state["scores"]["human"] += split

    for p in PLAYERS:
        tableau = new_state["tableaus"][p]
        by_type = collections.defaultdict(list)
        for card in tableau:
            by_type[card["card_type"]].append(card)
            
        for card_type, cards in by_type.items():
            effects = new_state["catalog"]["effects"].get(card_type, [])
            for op in effects:
                op_name = op.get("op")
                if op_name == "score_flat":
                    points = op.get("points", 0)
                    for card in cards:
                        new_state["scores"][p] += points * card.get("multiplier", 1)
                elif op_name == "score_per_set":
                    size = op.get("size", 1)
                    points = op.get("points", 0)
                    n = len(cards)
                    new_state["scores"][p] += (n // size) * points
                elif op_name == "score_tiered":
                    tiers = op.get("tiers", [])
                    n = len(cards)
                    if n > 0:
                        val = tiers[min(n, len(tiers)) - 1]
                        new_state["scores"][p] += val

    for p in PLAYERS:
        new_puddings = []
        for card in new_state["tableaus"][p]:
            card_type = card["card_type"]
            effects = new_state["catalog"]["effects"].get(card_type, [])
            is_pudding = False
            for op in effects:
                if op.get("op") == "score_at_end" and op.get("count_field") == "pudding":
                    is_pudding = True
            if is_pudding or "pudding" in card_type:
                new_puddings.append(card_type)
            else:
                new_state["discard"].append(card_type)
        new_state["puddings"][p].extend(new_puddings)
        new_state["tableaus"][p] = []
        
    return new_state

def score_game_end(state: State) -> State:
    new_state = copy.deepcopy(state)
    p_a = len(new_state["puddings"]["automa"])
    p_h = len(new_state["puddings"]["human"])
    
    first_pudding = 6
    for effects in new_state["catalog"]["effects"].values():
        for op in effects:
            if op.get("op") == "score_at_end" and op.get("count_field") == "pudding":
                first_pudding = op.get("first", 6)
                
    if p_a != p_h:
        if p_a > p_h:
            new_state["scores"]["automa"] += first_pudding
        else:
            new_state["scores"]["human"] += first_pudding
            
    return new_state

def legal_actions(state: State) -> list[Action]:
    if is_terminal(state):
        return []
        
    p = state[TO_PLAY]
    hand = state["hands"][p]
    
    actions = []
    unique_cards = sorted(list(set(hand)))
    for card_type in unique_cards:
        actions.append({
            LABEL: f"Play {card_type}",
            "card": card_type
        })
        
    has_chopsticks = any(c["card_type"] == "chopsticks" for c in state["tableaus"][p])
    if has_chopsticks and len(hand) >= 2:
        counts = collections.Counter(hand)
        card_types = sorted(list(counts.keys()))
        pairs = []
        for i, c1 in enumerate(card_types):
            if counts[c1] >= 2:
                pairs.append((c1, c1))
            for c2 in card_types[i+1:]:
                pairs.append((c1, c2))
                
        pairs.sort()
        for c1, c2 in pairs:
            actions.append({
                LABEL: f"Use Chopsticks to play {c1} and {c2}",
                "card1": c1,
                "card2": c2
            })
            
    return actions

def apply(state: State, action: Action) -> State:
    new_state = copy.deepcopy(state)
    p = new_state[TO_PLAY]
    
    new_state["pending_choices"][p] = action
    
    if p == "automa":
        new_state[TO_PLAY] = "human"
    else:
        new_state[TO_PLAY] = "automa"
        
    new_state[PLY] += 1
    
    if new_state["pending_choices"]["automa"] is not None and new_state["pending_choices"]["human"] is not None:
        for player in PLAYERS:
            choice = new_state["pending_choices"][player]
            if "card1" in choice and "card2" in choice:
                c1 = choice["card1"]
                c2 = choice["card2"]
                new_state["hands"][player].remove(c1)
                new_state["hands"][player].remove(c2)
                chopsticks_card = next((c for c in new_state["tableaus"][player] if c["card_type"] == "chopsticks"), None)
                if chopsticks_card:
                    new_state["tableaus"][player].remove(chopsticks_card)
                new_state["hands"][player].append("chopsticks")
                for card_type in [c1, c2]:
                    unpaired_wasabi = next((c for c in new_state["tableaus"][player] if c["card_type"] == "wasabi" and not c.get("paired")), None)
                    if unpaired_wasabi and "nigiri" in card_type:
                        unpaired_wasabi["paired"] = True
                        new_state["tableaus"][player].append({"card_type": card_type, "multiplier": 3})
                    elif card_type == "wasabi":
                        new_state["tableaus"][player].append({"card_type": card_type, "multiplier": 1, "paired": False})
                    else:
                        new_state["tableaus"][player].append({"card_type": card_type, "multiplier": 1})
            else:
                card_type = choice["card"]
                new_state["hands"][player].remove(card_type)
                unpaired_wasabi = next((c for c in new_state["tableaus"][player] if c["card_type"] == "wasabi" and not c.get("paired")), None)
                if unpaired_wasabi and "nigiri" in card_type:
                    unpaired_wasabi["paired"] = True
                    new_state["tableaus"][player].append({"card_type": card_type, "multiplier": 3})
                elif card_type == "wasabi":
                    new_state["tableaus"][player].append({"card_type": card_type, "multiplier": 1, "paired": False})
                else:
                    new_state["tableaus"][player].append({"card_type": card_type, "multiplier": 1})
                    
        new_state["pending_choices"]["automa"] = None
        new_state["pending_choices"]["human"] = None
        new_state[TURN] += 1

        new_state = _after_turn_cards_played(new_state)

    return new_state

def is_terminal(state: State) -> bool:
    return state.get("round", 1) > 3

def winner(state: State) -> str | None:
    if not is_terminal(state):
        raise ValueError("Match is not finished.")
    s_a = state["scores"]["automa"]
    s_h = state["scores"]["human"]
    if s_a > s_h:
        return "automa"
    elif s_h > s_a:
        return "human"
    else:
        p_a = len(state["puddings"]["automa"])
        p_h = len(state["puddings"]["human"])
        if p_a > p_h:
            return "automa"
        elif p_h > p_a:
            return "human"
        else:
            return None

def describe_state(state: State, viewer: Viewer) -> str:
    lines = []
    lines.append(f"--- Round {state.get('round', 1)} ---")
    lines.append(f"Scores: Automa={state['scores']['automa']}, Human={state['scores']['human']}")
    lines.append(f"Puddings: Automa={len(state['puddings']['automa'])}, Human={len(state['puddings']['human'])}")
    
    for p in PLAYERS:
        tableau_strs = []
        for c in state["tableaus"][p]:
            mult = f" x{c['multiplier']}" if c.get("multiplier", 1) > 1 else ""
            paired = " (wasabi)" if c.get("paired") else ""
            tableau_strs.append(f"{c['card_type']}{mult}{paired}")
        lines.append(f"{p.capitalize()}'s Tableau: {', '.join(tableau_strs) if tableau_strs else 'Empty'}")
        
    if viewer == Viewer.PUBLIC:
        lines.append(f"Automa Hand Count: {len(state['hands']['automa'])}")
        lines.append(f"Human Hand Count: {len(state['hands']['human'])}")
    elif viewer == Viewer.AUTOMA:
        lines.append(f"Your Hand: {', '.join(state['hands']['automa'])}")
        lines.append(f"Human Hand Count: {len(state['hands']['human'])}")
    elif viewer == Viewer.HUMAN:
        lines.append(f"Your Hand: {', '.join(state['hands']['human'])}")
        lines.append(f"Automa Hand Count: {len(state['hands']['automa'])}")
        
    return "\n".join(lines)

def check_invariants(state: State) -> list[str]:
    errors = []
    cards_in_deck = len(state.get("deck", []))
    cards_in_hands = sum(len(h) for h in state.get("hands", {}).values())
    cards_in_tableaus = sum(len(t) for t in state.get("tableaus", {}).values())
    cards_in_puddings = sum(len(p) for p in state.get("puddings", {}).values())
    cards_in_discard = len(state.get("discard", []))
    
    total_cards = cards_in_deck + cards_in_hands + cards_in_tableaus + cards_in_puddings + cards_in_discard
    if total_cards != 108:
        errors.append(f"Card conservation failure: expected 108 cards, found {total_cards}")
        
    for p in PLAYERS:
        score = state.get("scores", {}).get(p, 0)
        if score < 0:
            errors.append(f"Player {p} has negative score: {score}")
            
    return errors